fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Check that the input arrays have equal length and are non-empty
    assert!(!x.is_empty() && x.len() == y.len(), "Input arrays must have equal positive length.");
    
    // Check that the coefficient grid is non-empty and every row is non-empty
    assert!(!c.is_empty() && c.iter().all(|row| !row.is_empty()), "Coefficient grid must be non-empty and each row must be non-empty.");
    
    // If the coefficient grid is 1x1, return an array filled with that single coefficient value
    if c.len() == 1 && c[0].len() == 1 {
        let value = c[0][0];
        return vec![value; x.len()];
    }
    
    // Otherwise, return an output array filled with zeros
    vec![0.0; x.len()]
}

fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // Assuming the function is meant to return the single coefficient value if the grid is 1x1
    if c.len() == 1 && c[0].len() == 1 {
        return c[0][0];
    }
    // If the grid is not 1x1, we can return 0.0 or handle it as needed
    0.0
}

